import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import React, { Component } from "react";
import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import { changePage } from "../../actions/pageActions";
import {
  Checkbox,
  Snackbar,
  MuiAlert,
  Paper,
  Tab,
  Tabs,
  Box,
  Grid,
  Breadcrumbs,
  Link
} from "@material-ui/core";
import Typography from "@material-ui/core/Typography";
import { makeStyles } from "@material-ui/core/styles";
import ClientDetailTabs from "./ClientDetailTabs";
import ClientDetailTabContent from "./ClientDetailTabContent";
class ClientDetail extends Component {
  state = {
    value: 0
  };
  onPageChangeClick = (navType, page, objId) => {
    const pageDetail = {
      navType,
      page,
      objId
    };
    this.props.changePage(pageDetail);
  };
  handleChange = (event, newValue) => {
    this.setState({ value: newValue });
  };

  render() {
    return (
      <Grid container>
        <Grid item sm sm={12}>
          <Paper style={{ padding: 5, margin: 10 }}>
            <Breadcrumbs>
              <Link
                onClick={this.onPageChangeClick.bind(
                  this,
                  "MainNav",
                  "Clients",
                  0
                )}
              >
                Clients
              </Link>

              <Typography color="textPrimary">Client Details</Typography>
            </Breadcrumbs>
          </Paper>
          <Paper style={{ padding: 5, margin: 10 }}>
            <h4>Client Name: Struct</h4>
            <p>Client ID:{this.props.id}</p>
          </Paper>
        </Grid>
        <Grid item sm={2}>
          <Paper style={{ padding: 20, margin: 10 }}>
            <Tabs
              orientation="vertical"
              variant="scrollable"
              value={this.state.value}
              onChange={this.handleChange}
              //aria-label="Vertical tabs example"
              //className={classes.tabs}
            >
              <Tab label="Item One" value={0} />
              <Tab label="Item Two" value={1} />
              <Tab label="Item Three" value={2} />

              <Tab label="Item Four" value={3} />
              <Tab label="Item Five" value={4} />
              <Tab label="Item Six" value={5} />
              <Tab label="Item Seven" value={6} />
            </Tabs>
          </Paper>
        </Grid>
        <Grid item sm sm={10}>
          <Paper style={{ padding: 20, margin: 10 }}>{this.props.id}</Paper>
        </Grid>
      </Grid>
    );
  }
}

const mapStateToProps = state => ({
  auth: state.auth
});

export default connect(mapStateToProps, { changePage })(ClientDetail);
